from nodegraphqt import NodeGraph, PipeLayoutEnum, LayoutDirectionEnum

def zoom_in(graph: NodeGraph, factor: float = 1.2):
    """Zoom in the node graph view."""
    current_zoom = graph.get_zoom()
    graph.set_zoom(current_zoom * factor)

def zoom_out(graph: NodeGraph, factor: float = 1.2):
    """Zoom out the node graph view."""
    current_zoom = graph.get_zoom()
    graph.set_zoom(current_zoom / factor)

def reset_zoom(graph: NodeGraph):
    """Reset the zoom level to default."""
    graph.reset_zoom()

def set_layout_direction_horizontal(graph: NodeGraph):
    """Set layout direction to horizontal."""
    graph.set_layout_direction(LayoutDirectionEnum.HORIZONTAL)

def set_layout_direction_vertical(graph: NodeGraph):
    """Set layout direction to vertical."""
    graph.set_layout_direction(LayoutDirectionEnum.VERTICAL)

def open_session(graph: NodeGraph, file_path: str):
    """Open a session from file."""
    graph.load_session(file_path)

def import_session(graph: NodeGraph, file_path: str):
    """Import a session into the current graph."""
    graph.import_session(file_path)

def save_session(graph: NodeGraph, file_path: str):
    """Save the current session to file."""
    graph.save_session(file_path)

def clear_session(graph: NodeGraph):
    """Clear the current session."""
    graph.clear_session()

def clear_undo_history(graph: NodeGraph):
    """Clear the undo stack/history."""
    graph.clear_undo_stack()

def copy_nodes(graph: NodeGraph):
    """Copy selected nodes."""
    graph.copy_nodes()

def cut_nodes(graph: NodeGraph):
    """Cut selected nodes."""
    graph.cut_nodes()

def paste_nodes(graph: NodeGraph):
    """Paste nodes from clipboard."""
    graph.paste_nodes()

def delete_nodes(graph: NodeGraph):
    """Delete selected nodes."""
    graph.delete_nodes(graph.selected_nodes())

def extract_nodes(graph: NodeGraph):
    """Extract selected nodes."""
    graph.extract_nodes(graph.selected_nodes())

def clear_connections(graph: NodeGraph):
    """Clear connections of selected nodes."""
    for node in graph.selected_nodes():
        node.clear_connections()

def select_all_nodes(graph: NodeGraph):
    """Select all nodes."""
    graph.select_all()

def clear_selection(graph: NodeGraph):
    """Clear selection."""
    graph.clear_selection()

def invert_selection(graph: NodeGraph):
    """Invert selection."""
    graph.invert_selection()

def disable_nodes(graph: NodeGraph):
    """Disable selected nodes."""
    for node in graph.selected_nodes():
        node.set_disabled(True)

def duplicate_nodes(graph: NodeGraph):
    """Duplicate selected nodes."""
    graph.duplicate_nodes(graph.selected_nodes())

def expand_group_node(graph: NodeGraph):
    """Expand selected group nodes."""
    for node in graph.selected_nodes():
        if hasattr(node, 'expand_group_node'):
            node.expand_group_node()

def fit_zoom_to_selected(graph: NodeGraph):
    """Fit zoom level to selected nodes."""
    graph.fit_to_selection()

def show_undo_list(graph: NodeGraph):
    """Show the undo list dialog."""
    graph.undo_view()

def set_pipe_style_curved(graph: NodeGraph):
    """Set pipe style to curved."""
    graph.set_pipe_style(PipeLayoutEnum.CURVED)

def set_pipe_style_straight(graph: NodeGraph):
    """Set pipe style to straight."""
    graph.set_pipe_style(PipeLayoutEnum.STRAIGHT)

def set_pipe_style_angled(graph: NodeGraph):
    """Set pipe style to angled."""
    graph.set_pipe_style(PipeLayoutEnum.ANGLED)

def set_grid_none(graph: NodeGraph):
    """Set background grid to none."""
    graph.set_grid_mode('none')

def set_grid_dots(graph: NodeGraph):
    """Set background grid to dots."""
    graph.set_grid_mode('dots')

def set_grid_lines(graph: NodeGraph):
    """Set background grid to lines."""
    graph.set_grid_mode('lines')

def auto_layout_downstream(graph: NodeGraph):
    """Auto layout nodes downstream from selected nodes."""
    graph.auto_layout_nodes(direction='downstream')

def auto_layout_upstream(graph: NodeGraph):
    """Auto layout nodes upstream from selected nodes."""
    graph.auto_layout_nodes(direction='upstream')

def toggle_node_search(graph: NodeGraph):
    """Toggle the node search dialog."""
    graph.toggle_node_search()
